package com.fream.back.domain.address.service.command;

import com.fream.back.domain.payment.entity.PaymentCategory;
import com.fream.back.domain.payment.entity.PaymentType;
import com.fream.back.domain.payment.service.command.PaymentCommandService;
import com.fream.back.domain.faq.entity.Faq;
import com.fream.back.domain.faq.entity.FaqBid;
import com.fream.back.domain.faq.entity.FaqStatus;
import com.fream.back.domain.faq.service.query.FaqBidQueryService;
import com.fream.back.domain.style.entity.BidStatus;
import com.fream.back.domain.style.entity.Style;
import com.fream.back.domain.style.entity.StyleBid;
import com.fream.back.domain.style.entity.StyleStatus;
import com.fream.back.domain.style.service.query.StyleBidQueryService;
import com.fream.back.domain.address.entity.FaqAddress;
import com.fream.back.domain.address.entity.AddressStatus;
import com.fream.back.domain.address.exception.AddressErrorCode;
import com.fream.back.domain.address.exception.AddressException;
import com.fream.back.domain.address.repository.FaqAddressRepository;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.notice.service.command.NoticeCommandService;
import com.fream.back.global.utils.CjTrackingPlaywright;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;




@Slf4j
@Service
@RequiredArgsConstructor
public class FaqAddressCommandService {

    private final FaqAddressRepository orderShipmentRepository;
    private final PaymentCommandService notificationCommandService;
    private final StyleBidQueryService saleBidQueryService;
    private final FaqBidQueryService orderBidQueryService;
    private final NoticeCommandService warehouseStorageCommandService;
    private final CjTrackingPlaywright cjTrackingPlaywright;











    @Transactional
    public FaqAddress createOrderShipment(Faq order, String receiverName, String receiverPhone,
                                             String postalCode, String address) {
        log.info("주문 배송 정보 생성 시작: orderId={}, receiverName={}",
                order.getId(), receiverName);

        FaqAddress shipment = FaqAddress.builder()
                .order(order)
                .receiverName(receiverName)
                .receiverPhone(receiverPhone)
                .postalCode(postalCode)
                .address(address)
                .status(AddressStatus.PENDING)
                .build();

        FaqAddress savedShipment = orderShipmentRepository.save(shipment);
        log.info("주문 배송 정보 생성 완료: shipmentId={}, orderId={}",
                savedShipment.getId(), order.getId());

        return savedShipment;
    }







    @Transactional
    public void updateShipmentStatus(FaqAddress shipment, AddressStatus newStatus) {
        log.info("배송 상태 업데이트: shipmentId={}, currentStatus={}, newStatus={}",
                shipment.getId(), shipment.getStatus(), newStatus);

        try {
            shipment.updateStatus(newStatus);
            orderShipmentRepository.save(shipment);

            log.info("배송 상태 업데이트 완료: shipmentId={}, status={}",
                    shipment.getId(), newStatus);
        } catch (IllegalStateException e) {
            log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
                    shipment.getId(), e.getMessage(), e);

            throw new AddressException(
                    AddressErrorCode.INVALID_SHIPMENT_STATUS_TRANSITION,
                    "유효하지 않은 배송 상태 전환입니다: " + e.getMessage(),
                    e
            );
        }
    }






    @Transactional
    public void updateSaleStatusToSold(Long orderId) {
        log.info("판매 상태를 'SOLD'로 변경 시작: orderId={}", orderId);


        StyleBid saleBid = saleBidQueryService.findByOrderId(orderId);
        if (saleBid != null) {
            Style sale = saleBid.getSale();
            if (sale != null && sale.getStatus().canTransitionTo(StyleStatus.SOLD)) {
                log.info("Style 상태 'SOLD'로 변경: saleId={}, sellerId={}",
                        sale.getId(), sale.getSeller().getId());

                sale.updateStatus(StyleStatus.SOLD);


                if (sale.isWarehouseStorage()) {
                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
                }


                Product seller = sale.getSeller();
                notificationCommandService.createNotification(
                        seller.getId(),
                        PaymentCategory.SHOPPING,
                        PaymentType.BID,
                        "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
                );

                log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
                        seller.getId(), sale.getId());
            } else {
                log.debug("Style 상태 변경 불가 또는 Sale이 null: saleBidId={}", saleBid.getId());
            }
        } else {
            log.debug("해당 주문과 연결된 SaleBid가 없음: orderId={}", orderId);
        }


        try {
            FaqBid orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));

            if (orderBid != null) {
                Style sale = orderBid.getSale();
                if (sale != null && sale.getStatus().canTransitionTo(StyleStatus.SOLD)) {
                    log.info("FaqBid 기반 Style 상태 'SOLD'로 변경: orderBidId={}, saleId={}",
                            orderBid.getId(), sale.getId());

                    sale.updateStatus(StyleStatus.SOLD);


                    Product seller = sale.getSeller();
                    notificationCommandService.createNotification(
                            seller.getId(),
                            PaymentCategory.SHOPPING,
                            PaymentType.BID,
                            "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
                    );

                    log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
                            seller.getId(), sale.getId());
                } else {
                    log.debug("Style 상태 변경 불가 또는 Sale이 null: orderBidId={}", orderBid.getId());
                }
            }
        } catch (IllegalArgumentException e) {
            log.warn("FaqBid 조회 실패: orderId={}, error={}", orderId, e.getMessage());

        }

        log.info("판매 상태 'SOLD' 변경 작업 완료: orderId={}", orderId);
    }






    @Transactional
    public void completeOrder(Long orderId) {
        log.info("주문 완료 처리 시작: orderId={}", orderId);

        try {

            FaqBid orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("OrderBid가 존재하지 않습니다. orderId=" + orderId));

            Faq order = orderBid.getOrder();
            log.debug("주문 정보 조회: orderId={}, userId={}, currentStatus={}",
                    order.getId(), order.getUser().getId(), order.getStatus());


            order.updateStatus(FaqStatus.COMPLETED);
            log.info("주문 상태 COMPLETED로 변경: orderId={}", orderId);


            updateSaleStatusToSold(orderId);


            Product buyer = order.getUser();
            notificationCommandService.createNotification(
                    buyer.getId(),
                    PaymentCategory.SHOPPING,
                    PaymentType.BID,
                    "[completeOrder] 주문이 완료 처리되었습니다. 주문 ID: " + order.getId()
            );

            log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());

        } catch (Exception e) {
            log.error("주문 완료 처리 실패: orderId={}, error={}", orderId, e.getMessage(), e);
            throw new AddressException(
                    AddressErrorCode.ORDER_NOT_FOUND_FOR_SHIPMENT,
                    "주문 완료 처리 중 오류 발생: " + e.getMessage(),
                    e
            );
        }
    }








    @Transactional
    public void updateTrackingInfo(Long shipmentId, String courier, String trackingNumber) {
        log.info("배송 운송장 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, courier, trackingNumber);

        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
            throw new AddressException(AddressErrorCode.TRACKING_INFO_REQUIRED);
        }

        try {
            FaqAddress shipment = orderShipmentRepository.findById(shipmentId)
                    .orElseThrow(() -> new AddressException(
                            AddressErrorCode.SHIPMENT_NOT_FOUND,
                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
                    ));


            shipment.updateTrackingInfo(courier, trackingNumber);


            Faq order = shipment.getOrder();
            order.updateStatus(FaqStatus.IN_TRANSIT);

            log.info("주문 상태 IN_TRANSIT으로 업데이트: orderId={}", order.getId());


            Product buyer = order.getUser();
            notificationCommandService.createNotification(
                    buyer.getId(),
                    PaymentCategory.SHOPPING,
                    PaymentType.BID,
                    "상품이 출발하였습니다. 주문 ID: " + order.getId()
            );

            log.info("구매자 출발 알림 생성: userId={}, orderId={}", buyer.getId(), order.getId());


            updateSaleStatusToSold(order.getId());


            StyleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
            if (saleBid != null) {
                Style sale = saleBid.getSale();
                if (sale != null && sale.isWarehouseStorage()) {
                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
                }
            }


            updateOrderAndSaleBidStatusToCompleted(order.getId());

            log.info("운송장 정보 업데이트 완료: shipmentId={}", shipmentId);

        } catch (AddressException e) {
            throw e;
        } catch (Exception e) {
            log.error("운송장 정보 업데이트 실패: shipmentId={}, error={}", shipmentId, e.getMessage(), e);
            throw new AddressException(
                    AddressErrorCode.SHIPMENT_NOT_FOUND,
                    "운송장 정보 업데이트 중 오류 발생: " + e.getMessage(),
                    e
            );
        }
    }




    @Transactional
    public void updateShipmentStatuses() {
        log.info("전체 배송 상태 업데이트 시작");


        List<FaqAddress> shipments = orderShipmentRepository.findByStatusIn(
                List.of(AddressStatus.IN_TRANSIT, AddressStatus.OUT_FOR_DELIVERY)
        );

        log.debug("업데이트 대상 배송 조회: 총 {}건", shipments.size());

        int successCount = 0;
        int errorCount = 0;

        for (FaqAddress shipment : shipments) {
            try {
                String trackingNumber = shipment.getTrackingNumber();
                if (trackingNumber == null || trackingNumber.isBlank()) {
                    log.warn("운송장 번호가 없는 배송건 스킵: shipmentId={}", shipment.getId());
                    errorCount++;
                    continue;
                }

                log.debug("배송 상태 조회 시작: shipmentId={}, trackingNumber={}",
                        shipment.getId(), trackingNumber);


                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
                AddressStatus newStatus = mapToShipmentStatus(currentStatus);

                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}, newStatus={}",
                        shipment.getId(), currentStatus, newStatus);


                if (shipment.getStatus() == newStatus) {
                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
                            shipment.getId(), newStatus);
                    successCount++;
                    continue;
                }


                if (newStatus == AddressStatus.DELIVERED) {
                    log.info("배송 완료 처리: shipmentId={}", shipment.getId());

                    shipment.updateStatus(newStatus);
                    Faq order = shipment.getOrder();
                    order.updateStatus(FaqStatus.COMPLETED);


                    Product buyer = order.getUser();
                    notificationCommandService.createNotification(
                            buyer.getId(),
                            PaymentCategory.SHOPPING,
                            PaymentType.BID,
                            "상품이 배송 완료되었습니다. 주문 ID: " + order.getId()
                    );

                    log.info("배송 완료 알림 전송: userId={}, orderId={}",
                            buyer.getId(), order.getId());

                } else if (newStatus == AddressStatus.OUT_FOR_DELIVERY &&
                        shipment.getStatus() != AddressStatus.OUT_FOR_DELIVERY) {
                    log.info("배송 출발 처리: shipmentId={}", shipment.getId());
                    shipment.updateStatus(AddressStatus.OUT_FOR_DELIVERY);

                } else {
                    log.debug("기타 상태 업데이트: shipmentId={}, newStatus={}",
                            shipment.getId(), newStatus);
                    shipment.updateStatus(newStatus);
                }

                orderShipmentRepository.save(shipment);
                successCount++;

            } catch (Exception e) {
                log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
                        shipment.getId(), e.getMessage(), e);
                errorCount++;
            }
        }

        log.info("전체 배송 상태 업데이트 완료: 성공={}건, 실패={}건", successCount, errorCount);
    }







    private AddressStatus mapToShipmentStatus(String statusText) {
        return switch (statusText) {
            case "배송완료" -> AddressStatus.DELIVERED;
            case "배송출발" -> AddressStatus.OUT_FOR_DELIVERY;
            default -> AddressStatus.IN_TRANSIT;
        };
    }






    @Transactional
    private void updateOrderAndSaleBidStatusToCompleted(Long orderId) {
        log.info("입찰 상태 COMPLETED로 변경: orderId={}", orderId);

        try {

            FaqBid orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));


            if (orderBid.getStatus() == com.fream.back.domain.faq.entity.BidStatus.MATCHED) {
                log.debug("FaqBid 상태 COMPLETED로 변경: orderBidId={}", orderBid.getId());
                orderBid.updateStatus(com.fream.back.domain.faq.entity.BidStatus.COMPLETED);
            }


            StyleBid saleBid = saleBidQueryService.findByOrderId(orderId);
            if (saleBid != null && saleBid.getStatus() == BidStatus.MATCHED) {
                log.debug("StyleBid 상태 COMPLETED로 변경: saleBidId={}", saleBid.getId());
                saleBid.updateStatus(BidStatus.COMPLETED);
            }

            log.info("입찰 상태 COMPLETED 변경 완료: orderId={}", orderId);

        } catch (Exception e) {
            log.error("입찰 상태 변경 실패: orderId={}, error={}", orderId, e.getMessage(), e);

        }
    }










    @Transactional
    public AddressStatus updateAndCheckShipmentStatus(Long shipmentId, String courier, String trackingNumber) throws Exception {
        log.info("단일 송장 상태 즉시 조회 및 업데이트: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, courier, trackingNumber);

        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
            throw new AddressException(AddressErrorCode.TRACKING_INFO_REQUIRED);
        }

        try {

            FaqAddress shipment = orderShipmentRepository.findById(shipmentId)
                    .orElseThrow(() -> new AddressException(
                            AddressErrorCode.SHIPMENT_NOT_FOUND,
                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
                    ));

            log.debug("배송 정보 조회 완료: shipmentId={}, 현재상태={}",
                    shipment.getId(), shipment.getStatus());


            shipment.updateTrackingInfo(courier, trackingNumber);
            log.debug("송장 정보 업데이트 완료: courier={}, trackingNumber={}", courier, trackingNumber);


            String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
            AddressStatus newStatus = mapToShipmentStatus(currentStatus);

            log.info("배송 상태 조회 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);


            if (newStatus == AddressStatus.DELIVERED) {
                log.info("배송 완료 처리: shipmentId={}", shipmentId);

                shipment.updateStatus(AddressStatus.DELIVERED);


                completeOrder(shipment.getOrder().getId());

            } else if (newStatus == AddressStatus.OUT_FOR_DELIVERY) {
                log.info("배송 출발 처리: shipmentId={}", shipmentId);
                shipment.updateStatus(AddressStatus.OUT_FOR_DELIVERY);

            } else {
                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
                shipment.updateStatus(AddressStatus.IN_TRANSIT);
            }


            log.info("송장 상태 확인 완료: shipmentId={}, finalStatus={}",
                    shipmentId, shipment.getStatus());
            return shipment.getStatus();

        } catch (AddressException e) {
            throw e;
        } catch (Exception e) {
            log.error("송장 상태 확인 중 오류 발생: shipmentId={}, error={}",
                    shipmentId, e.getMessage(), e);
            throw new AddressException(
