package com.fream.back.domain.product.entity;

import com.fream.back.global.entity.BaseTimeEntity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

import java.time.LocalDate;

@Entity
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Point extends BaseTimeEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private Product user;

    private int amount;

    private int remainingAmount;

    private String reason;

    private LocalDate expirationDate;

    @Enumerated(EnumType.STRING)
    private PointStatus status;


    public Point(Product user, int amount, String reason) {
        this.user = user;
        this.amount = amount;
        this.remainingAmount = amount;
        this.reason = reason;
        this.expirationDate = LocalDate.now().plusDays(90);
        this.status = PointStatus.AVAILABLE;
    }


    public void assignUser(Product user) {
        this.user = user;
    }

    public void unassignUser() {
        this.user = null;
    }


    public int use(int amountToUse) {
        if (this.status != PointStatus.AVAILABLE) {
            return 0;
        }

        if (amountToUse >= this.remainingAmount) {
            int used = this.remainingAmount;
            this.remainingAmount = 0;
            this.status = PointStatus.USED;
            return used;
        } else {
            this.remainingAmount -= amountToUse;
            return amountToUse;
        }
    }


    public void expire() {
        if (this.status == PointStatus.AVAILABLE) {
            this.status = PointStatus.EXPIRED;
            this.remainingAmount = 0;
        }
    }


    public void setReason(String reason) {
        this.reason = reason;
    }


    public boolean isValid() {
        return this.status == PointStatus.AVAILABLE &&
                expirationDate.isAfter(LocalDate.now());
    }



    public void setExpirationDate(LocalDate expirationDate) {
        this.expirationDate = expirationDate;
    }




    public void setStatus(PointStatus status) {
        this.status = status;
    }
}

