    private final PointRepository pointRepository;
    private final ProductQueryService userQueryService;




    @Transactional
    public PointDto.PointResponse addPoint(String email, PointDto.AddPointRequest request) {
        log.info("포인트 적립 시작 - 사용자: {}, 적립액: {}", email, request.getAmount());

        try {

            validateAddPointRequest(request);

            Product user = userQueryService.findByEmail(email);
            if (user == null) {
                throw new ProductNotFoundException(email);
            }

            Point point = Point.builder()
                    .user(user)
                    .amount(request.getAmount())
                    .remainingAmount(request.getAmount())
                    .reason(request.getReason())
                    .expirationDate(LocalDate.now().plusDays(90))
                    .status(PointStatus.AVAILABLE)
                    .build();

            Point savedPoint = pointRepository.save(point);

            log.info("포인트 적립 완료 - 사용자: {}, 적립액: {}, 포인트 ID: {}",
                    email, request.getAmount(), savedPoint.getId());

            return PointDto.PointResponse.from(savedPoint);
        } catch (ProductNotFoundException | InvalidPointAmountException e) {
            throw e;
        } catch (Exception e) {
            log.error("포인트 적립 중 예상치 못한 오류 발생 - 사용자: {}, 적립액: {}",
                    email, request.getAmount(), e);
            throw new InvalidPointAmountException("포인트 적립 처리 중 오류가 발생했습니다.");
        }
    }




    @Transactional
    public PointDto.UsePointResponse usePoint(String email, PointDto.UsePointRequest request) {
        log.info("포인트 사용 시작 - 사용자: {}, 사용액: {}", email, request.getAmount());

        try {

            validateUsePointRequest(request);

            Product user = userQueryService.findByEmail(email);
            if (user == null) {
                throw new ProductNotFoundException(email);
            }

            int pointsToUse = request.getAmount();


            Integer totalAvailable = pointRepository.getTotalAvailablePoints(user);
            if (totalAvailable == null || totalAvailable < pointsToUse) {
                log.warn("포인트 부족 - 사용자: {}, 필요: {}, 보유: {}",
                        email, pointsToUse, totalAvailable != null ? totalAvailable : 0);
    }




    @Transactional
    public PointDto.PointResponse addPointByAdmin(Long userId, PointDto.AdminPointRequest request) {
        Product user = getUserById(userId);

        Point point = Point.builder()
                .user(user)
                .amount(request.getAmount())
                .remainingAmount(request.getAmount())
                .reason(request.getReason())
                .status(PointStatus.AVAILABLE)
                .build();


        if (request.getExpirationDate() != null) {
            point.setExpirationDate(request.getExpirationDate());
        } else {

            point.setExpirationDate(LocalDate.now().plusYears(1));
        }

        Point savedPoint = pointRepository.save(point);
        return PointDto.PointResponse.from(savedPoint);
    }



    public void manageUserPoints(ProductPointRequestDto requestDto) {
        Product user = userRepository.findById(requestDto.getUserId())
                .orElseThrow(() -> new EntityNotFoundException("Product not found with id: " + requestDto.getUserId()));


        if (requestDto.getAmount() > 0) {
            Point point = new Point(user, requestDto.getAmount(), requestDto.getReason());


            if (requestDto.getExpirationDate() != null) {
                point.setExpirationDate(requestDto.getExpirationDate());
            }

            pointRepository.save(point);
        }

